-- Partial snapshot. Prefer `npx tsx --env-file=.env.local scripts/apply-coach-catalog.ts`
-- for a full voice replace (already applied on prod 2026-09-04).
-- Reward / punishment rewrite: start, mid, last third, bonus, exit, resume, missed week, drop, hardness 1-2.
-- {name} is filled in the app as first name. Apply on PlanetScale by hand. Safe to re-run.

DELETE FROM coach_lines
WHERE bucket IN (
  'initial', 'mid', 'final', 'exit', 'bonus_complete', 'resume', 'missed_week', 'set_down', 'hardness_1', 'hardness_2'
);

