('master', 'initial', 3, NULL, 'Set your feet. I am watching the first inch. Mobility in the stance is what lets the power out.', 1),
('master', 'initial', 4, NULL, 'Soft start is for other rooms. Here you lock in. That is stamina for the whole hour.', 1),
('master', 'initial', 5, NULL, 'Unrack. I did not bring you here to negotiate. Lock this and the hour buys definition.', 1),
