('master', 'initial', 16, NULL, 'You don''t ask where we''re going. Sit under the bar. Hands on. That is how growth stays in the muscle.', 1),
('master', 'initial', 17, NULL, 'Stand straight. Carry yourself like the power already went up. Then make that true.', 1),
('master', 'initial', 18, NULL, 'I am structured. Match me on this first plate and the hour builds lean.', 1),
