('luna', 'final', 2, NULL, 'Let the effort feel light. The weight is not. Moving it anyway is power.', 1),
('luna', 'final', 3, NULL, 'This breath. This movement. Then the next. That is how definition settles in.', 1),
('luna', 'final', 4, NULL, 'Close the way you opened. Awake. A present finish is lean you can start with next time.', 1),
