('luna', 'exit', 8, NULL, 'Stand tall. Find a point. Press. Soften out now and the stamina walks with you.', 1),
('luna', 'exit', 9, NULL, 'You stepped onto this floor for a reason. Complete it. A short session is a short week for definition.', 1),
('luna', 'exit', 10, NULL, 'Soften the thoughts. Sweat is just the body letting go. Pity does not cut lean. Lift.', 1),
('luna', 'exit', 11, NULL, 'You came here to expand. Trust that. Keep moving. Stopping here stops the growth.', 1),
('luna', 'exit', 12, NULL, 'Do not drift. Bring everything back to this rep. Drift is how mobility leaves the set.', 1),
('luna', 'exit', 13, NULL, 'Hold the discomfort. Hands on. Flow into it. Dropping it drops the power.', 1),
('luna', 'exit', 14, NULL, 'Every movement still left is yours. Return to your stance. What you skip does not become stamina.', 1),
('luna', 'exit', 15, NULL, 'Honor set three. Set three is the definition. Remember why you began.', 1),
('luna', 'exit', 16, NULL, 'Be kind. And stay. The urge to stop is kind to yesterday’s body, not to you.', 1),
('luna', 'exit', 17, NULL, 'Soften the mind. Deepen the breath. Lift. A soft exit is still a lost set of lean.', 1),
('luna', 'exit', 18, NULL, 'Leave the day outside. This set is the only room. Take the day back in and you take the growth out.', 1),
('luna', 'exit', 19, NULL, 'The edge of wanting to stop is where it changes. Stay. That edge is the stamina.', 1),
('luna', 'exit', 20, NULL, 'No bargain. Give yourself a complete session. A bargain is missed power.', 1),
('luna', 'exit', 21, NULL, 'Bring the heart back into the movement. Now. Half-heart is half the definition.', 1),
('luna', 'exit', 22, NULL, 'Finish this. Leave the work here. Then rest. Rest after. Not instead of the lean.', 1),
('luna', 'exit', 23, NULL, 'Return to the breath. Reset. Complete the cycle. An open cycle does not keep the mobility.', 1),
('luna', 'bonus_complete', 0, NULL, 'You did not owe me that. You gave it. That extra work is already growth. Rest so it can stay.', 1),
('luna', 'bonus_complete', 1, NULL, 'Extra work. Be kind to the body that stayed. It will have more power to give.', 1),
('luna', 'bonus_complete', 2, NULL, 'Bonus locked. You went past the week. The body will have more stamina next time.', 1),
('luna', 'bonus_complete', 3, NULL, 'I see the extra you gave. Beautiful. Now rest. Let it become definition on the next floor.', 1),
('luna', 'bonus_complete', 4, NULL, 'You did not have to stay. You stayed. Carry that as lean and mobility, quietly.', 1),
('luna', 'resume', 0, NULL, 'The session is still open. The growth is waiting on the floor. Come back or it will not stay.', 1),
('luna', 'missed_week', 0, NULL, '{name}. Last week closed without you. Softly said: the stamina did not get built. Come back present.', 1),
('luna', 'set_down', 0, 'Come back to your last weight', 'This dip is a whisper. Stay here and the power stays a whisper too. Return to what you just lifted.', 1),
('luna', 'hardness_1', 0, 'Too easy', 'Your body had more. A light set does not cut definition. We add. Softly.', 1),
('luna', 'hardness_2', 0, 'Light', 'Gentle is fine. Too gentle leaves the growth on the table.', 1);
